/**
 * @tx-wat/alert-registry-bindings
 *
 * TypeScript bindings for the AlertRegistry Soroban smart contract.
 *
 * This file is the hand-maintained entry point. The type-safe client is
 * generated by `stellar contract bindings typescript` into `dist/`, and the
 * generator bakes in the contract ID that `scripts/deployment_address.py`
 * reads from DEPLOYMENTS.md at build time. This entry re-exports everything
 * from the generated bindings and adds the network map so consumers can do:
 *
 *   import { Client, networks } from "@tx-wat/alert-registry-bindings";
 *
 * @see https://github.com/Tx-wat/contracts
 */

import { networks as generatedNetworks } from "../dist/index.js";

// ── Re-export everything from the generated bindings ─────────────────────────
export * from "../dist/index.js";

// ── Network address map ───────────────────────────────────────────────────────
// DEPLOYMENTS.md is the source of truth. The testnet contract ID comes from the
// generated bindings, which were built from the address resolved out of it.

export interface NetworkConfig {
  /** Deployed contract ID (56-character Stellar address starting with C). */
  contractId: string;
  /** Stellar network passphrase. */
  networkPassphrase: string;
  /** Soroban RPC endpoint. */
  rpcUrl: string;
}

export type NetworkName = "testnet" | "mainnet";

export const networks = {
  testnet: {
    contractId: generatedNetworks.testnet.contractId,
    networkPassphrase: "Test SDF Network ; September 2015",
    rpcUrl: "https://soroban-testnet.stellar.org",
  },
  mainnet: {
    // Not yet deployed on mainnet — see DEPLOYMENTS.md.
    contractId: "",
    networkPassphrase: "Public Global Stellar Network ; September 2015",
    rpcUrl: "",
  },
} as const satisfies Record<NetworkName, NetworkConfig>;
